using System;using System.Linq;using System.Windows.Forms;namespace MiniMartPOS{public partial class TransactionDetailsForm:Form{private readonly int saleID;public TransactionDetailsForm():this(0){}public TransactionDetailsForm(int id){saleID=id;InitializeComponent();if(System.ComponentModel.LicenseManager.UsageMode==System.ComponentModel.LicenseUsageMode.Designtime)return;UiStyle.PolishForm(this);LoadData();}private void LoadData(){Sale s=DatabaseData.Sales.First(x=>x.SaleID==saleID);User u=DatabaseData.Users.First(x=>x.UserID==s.UserID);lblTransaction.Text=s.TransactionNo;lblInfo.Text=s.SaleDate.ToString("MMM d, yyyy h:mm tt")+"   |   "+s.PaymentMethod+"   |   "+u.FullName;lblTotal.Text="Total: ₱"+s.TotalAmount.ToString("N2")+"   Cash: ₱"+s.CashReceived.ToString("N2")+"   Change: ₱"+s.ChangeAmount.ToString("N2");var items=from si in DatabaseData.SaleItems join m in DatabaseData.MenuItems on si.MenuItemID equals m.MenuItemID where si.SaleID==saleID select new{m.ItemName,si.Quantity,si.UnitPrice,si.Subtotal};foreach(var x in items)dgvItems.Rows.Add(x.ItemName,x.Quantity,"₱"+x.UnitPrice.ToString("N2"),"₱"+x.Subtotal.ToString("N2"));}}}
